ALTER TABLE public.maintenance_agreements ADD COLUMN pricing_mode text NOT NULL DEFAULT 'itemised' CHECK(pricing_mode IN ('itemised','collective')), ADD COLUMN collective_price numeric CHECK(collective_price>=0);
CREATE OR REPLACE FUNCTION public.aggregate_agreement_assets() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.maintenance_agreements SET annual_price=CASE WHEN pricing_mode='collective' THEN collective_price ELSE (SELECT sum(annual_price) FROM public.agreement_assets WHERE agreement_id=NEW.agreement_id) END,start_date=(SELECT min(start_date) FROM public.agreement_assets WHERE agreement_id=NEW.agreement_id),end_date=(SELECT max(end_date) FROM public.agreement_assets WHERE agreement_id=NEW.agreement_id) WHERE id=NEW.agreement_id; RETURN NEW; END $$;
DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.guard_agreement_header()'::regprocedure) INTO d; d=replace(d,'DECLARE d public.document_masters; BEGIN','DECLARE d public.document_masters; BEGIN IF NEW.pricing_mode=''collective'' AND NEW.collective_price IS NULL THEN RAISE EXCEPTION ''Enter a collective agreed price''; END IF; IF TG_OP=''UPDATE'' AND EXISTS(SELECT 1 FROM public.agreement_assets WHERE agreement_id=NEW.id) AND (NEW.pricing_mode,NEW.collective_price) IS DISTINCT FROM (OLD.pricing_mode,OLD.collective_price) THEN RAISE EXCEPTION ''Agreed pricing is frozen; create a new contract''; END IF;'); d=replace(d,'SELECT sum(annual_price),min(start_date),max(end_date)','SELECT CASE WHEN NEW.pricing_mode=''collective'' THEN NEW.collective_price ELSE sum(annual_price) END,min(start_date),max(end_date)'); EXECUTE d;
SELECT pg_get_functiondef('public.save_equipment_contract(jsonb,jsonb,uuid)'::regprocedure) INTO d; d=replace(d,'annual_price,project_price,notes) VALUES','annual_price,project_price,notes,pricing_mode,collective_price) VALUES'); d=replace(d,'coalesce(_header->>''notes'','''')) RETURNING','coalesce(_header->>''notes'',''''),coalesce(_header->>''pricing_mode'',''itemised''),nullif(_header->>''collective_price'','''')::numeric) RETURNING'); EXECUTE d;
SELECT pg_get_functiondef('public.client_contract_coverage(uuid)'::regprocedure) INTO d; d=replace(d,'''price'',a.annual_price,','''price'',a.annual_price,''pricing_mode'',a.pricing_mode,'); EXECUTE d; END $$;
CREATE FUNCTION public.save_client_document_assignments(_client uuid,_assignments jsonb) RETURNS void LANGUAGE plpgsql SET search_path=public AS $$ DECLARE c uuid=public.current_company_id(); row jsonb; m uuid; s uuid; e uuid; BEGIN
IF NOT public.member_commercial_can('contracts') OR NOT public.company_module_access(c,'core') THEN RAISE EXCEPTION 'Core contract access required'; END IF;
IF NOT EXISTS(SELECT 1 FROM public.clients WHERE id=_client AND company_id=c) THEN RAISE EXCEPTION 'Client unavailable'; END IF;
IF jsonb_typeof(_assignments)<>'array' OR jsonb_array_length(_assignments)>2000 THEN RAISE EXCEPTION 'Invalid document assignments'; END IF;
FOR row IN SELECT value FROM jsonb_array_elements(_assignments) LOOP m=(row->>'master_id')::uuid; s=nullif(row->>'site_id','')::uuid; e=nullif(row->>'asset_id','')::uuid;
IF NOT EXISTS(SELECT 1 FROM public.document_masters WHERE id=m AND company_id=c AND state='active') THEN RAISE EXCEPTION 'Choose a published company document'; END IF;
IF s IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.sites WHERE id=s AND client_id=_client AND company_id=c) THEN RAISE EXCEPTION 'Site unavailable'; END IF;
IF e IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.assets WHERE id=e AND client_id=_client AND company_id=c AND (s IS NULL OR site_id=s)) THEN RAISE EXCEPTION 'Equipment unavailable'; END IF;
IF coalesce((row->>'selected')::boolean,false) THEN IF NOT EXISTS(SELECT 1 FROM public.document_attachments WHERE company_id=c AND client_id=_client AND master_id=m AND site_id IS NOT DISTINCT FROM s AND asset_id IS NOT DISTINCT FROM e) THEN INSERT INTO public.document_attachments(company_id,client_id,master_id,site_id,asset_id) VALUES(c,_client,m,s,e); END IF;
ELSE DELETE FROM public.document_attachments WHERE company_id=c AND client_id=_client AND master_id=m AND site_id IS NOT DISTINCT FROM s AND asset_id IS NOT DISTINCT FROM e; END IF; END LOOP; END $$;
REVOKE ALL ON FUNCTION public.save_client_document_assignments(uuid,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.save_client_document_assignments(uuid,jsonb) TO authenticated;